// Bundled (preinstalled) fonts: static metadata + build-time coverage.
// Coverage is generated by scripts/gen-bundled-manifest.py from each font's
// cmap (the WOFF2 conversion does not change the cmap).

import type { Coverage } from "./cmap";
import coverageData from "../bundled-coverage.json";

export interface BundledFace {
  weight: number;
  italic: boolean;
  /** File name inside public/fonts/. */
  file: string;
  /** Key into bundled-coverage.json. */
  coverageId: string;
}

export interface BundledFont {
  id: string;
  /** Display name shown in the picker before the font itself is loaded. */
  name: string;
  author: string;
  /** Original distribution page. */
  sourceUrl: string;
  /** License / terms file inside public/licenses/. */
  licenseFile: string;
  licenseLabel: string;
  faces: BundledFace[];
}

const regular = (file: string, coverageId: string): BundledFace => ({
  weight: 400,
  italic: false,
  file,
  coverageId,
});

