const coverageMap = coverageData as unknown as Record<string, Array<[number, number]>>;

export function bundledCoverage(coverageId: string): Coverage | null {
  return coverageMap[coverageId] ?? null;
}

/** Absolute URL of a bundled face file, resolved against the page. */
export function bundledFaceUrl(face: BundledFace): string {
  return new URL(`fonts/${face.file}`, document.baseURI).href;
}

export function bundledLicenseUrl(font: BundledFont): string {
  return new URL(`licenses/${font.licenseFile}`, document.baseURI).href;
}
